const $=s=>document.querySelector(s), key='xu-family-garden-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Taipei'}).format(new Date());
let db;try{db=JSON.parse(localStorage.getItem(key))}catch{}db=db&&db.version===1?db:{version:1,children:{girl:{level:'easy',minutes:10,checks:{},logs:[],sessions:[],extra:''},boy:{level:'easy',minutes:10,checks:{},logs:[],sessions:[],extra:''}}};
let child='girl', page='home', currentTask=null,remaining=0,total=0,interval=null,endTime=0;
const profiles={girl:{name:'彗瑄',full:'徐彗瑄',birth:'2018-07-29',age:'8 歲',grade:'小學三年級',traits:['坐著看書或上課時容易想睡，提醒後有時能撐住。','偶爾白天疲倦；偶爾鼻塞、打呼，持續觀察睡眠作息。','平常約 21:30–22:00 上床，入睡約 30–60 分鐘（家長先前描述，待更新）。'],unknown:'待補充：喜愛的活動、目前作息、老師近期觀察、挫折時反應。'},boy:{name:'邦盛',full:'徐邦盛',birth:'2020-03-11',age:'6 歲',grade:'小學一年級',traits:['開始做事後容易分心，交辦常需要重複提醒。','上課有講話、插嘴、坐不住的情形；喜歡的活動可以較投入。','被糾正或遇到不會的事情容易生氣，練習先停一下、說出需要。'],unknown:'待補充：目前作業時間、有效的提醒方式、偏好獎勵、老師近期觀察。'}};
const tasks={focus:{title:'小小專注探險',icon:'⌕',area:'專注力',desc:'一次只做一小步，分心了就溫柔地回來。',steps:{easy:'準備一小段作業或一張圖。先說出「我現在要做什麼」，完成一題或找出 3 個指定物件。',normal:'準備一小段作業，先自己選 2 題。每完成一題，在紙上畫一個小點，再繼續下一題。',challenge:'先說出接下來的 3 個小步驟，依序完成；發現分心時，自己指回目前的步驟。'},prompt:'「我們先做這一小步。我會在旁邊，分心了就指回這裡。」'},stop:{title:'紅綠燈小隊長',icon:'◉',area:'自我控制',desc:'綠燈走、紅燈停，練習先看訊號再行動。',steps:{easy:'家長說「綠燈」時原地踏步，說「紅燈」時停下。慢慢切換，每輪之間休息。',normal:'加入「黃燈」慢慢走；聽完訊號再做動作，家長與孩子輪流當隊長。',challenge:'由孩子先複述紅、黃、綠燈規則，再練習不規則切換；錯了就一起重來。'},prompt:'「你剛才有等一下再動，這就是練習。這一輪我們再試一次。」'},calm:{title:'生氣小雲朵',icon:'☁',area:'情緒調節',desc:'先停一下、說感受，再選一個可以做的動作。',steps:{easy:'用手畫一朵雲，說「我現在覺得……」。自然慢慢呼吸，選擇喝水、休息或請人陪伴。',normal:'用一個輕微的小挫折情境，練習「停一下 → 說感受 → 說需要」，例如「我不會，我想請你提示第一步」。',challenge:'輪流扮演遇到不會的題目或被提醒的情境；孩子說出感受，並選擇休息或請求協助後再試。'},prompt:'「你不喜歡被糾正，我知道。我們先停一下；你要休息，還是要我提示第一步？」'},homework:{title:'作業起步儀式',icon:'✎',area:'作業習慣',desc:'清出桌面、選第一題，讓開始變得簡單。',steps:{easy:'桌上只留現在需要的物品。孩子自己選第一題，說出開始動作，家長只給一個簡短提醒。',normal:'用紙寫「準備 → 做一題 → 檢查」。每做完一步就畫勾，家長等孩子回應後再提醒。',challenge:'孩子自己排 3 個作業小步驟並開始；分心後看清單找回下一步，最後自己檢查。'},prompt:'「你想先從哪一題開始？先做第一步，完成後讓我看看。」'},move:{title:'醒醒身體小伸展',icon:'☀',area:'精神觀察',desc:'先看看精神，再決定今天適合的練習量。',steps:{easy:'站起來，慢慢伸手、踏步，喝一口水。問孩子「現在比較清醒，還是仍想休息？」',normal:'輪流帶 3 個輕鬆伸展動作，再觀察精神。仍想睡就停止練習，記錄今天狀況。',challenge:'孩子自己選 3 個舒適動作，輪流帶領。結束後描述精神變化，不用勉強撐住。'},prompt:'「你現在想睡嗎？我們先動一動看看；還是累，就先休息。」'}};
function save(){try{localStorage.setItem(key,JSON.stringify(db))}catch{toast('瀏覽器無法儲存，請先匯出備份。');return false}return true}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').style.display='none',3200)}
function data(){return db.children[child]}function check(){return data().checks[today()]||'unknown'}
function plan(){let ids=child==='boy'?['homework','focus','calm']:['move','focus','stop'];let c=check();if(c==='angry')ids=['calm','stop','homework'];if(c==='distracted')ids=['stop','focus','homework'];if(c==='tired')ids=['move','calm'];return ids}
function nextTask(){return plan().find(id=>!completed(id))||null}
function completed(id){return data().sessions.some(s=>s.date===today()&&s.task===id)}
function durations(){let ids=plan(),m=data().minutes;return ids.map((_,i)=>Math.floor(m/ids.length)+(i<m%ids.length?1:0))}
function week(offset=0){let now=new Date(today()+'T12:00:00+08:00');let day=now.getUTCDay();now.setUTCDate(now.getUTCDate()-((day+6)%7)+offset*7);return Array.from({length:7},(_,i)=>{let d=new Date(now);d.setUTCDate(d.getUTCDate()+i);return d.toISOString().slice(0,10)})}
function sessionsIn(dates){return data().sessions.filter(s=>dates.includes(s.date))}
function weekChart(){let dates=week();let max=Math.max(3,...dates.map(d=>data().sessions.filter(s=>s.date===d).length));return '<div class="miniweek">'+dates.map((d,i)=>{let n=data().sessions.filter(s=>s.date===d).length;return `<div class="day ${d===today()?'today':''}" title="${d}：${n} 次"><div class="bar"><i style="height:${Math.max(4,n/max*64)}px"></i></div>${['一','二','三','四','五','六','日'][i]}<br>${n? n+'次':'—'}</div>`}).join('')+'</div>'}
function garden(){return `<svg class="garden" viewBox="0 0 260 200" aria-hidden="true"><ellipse cx="140" cy="184" rx="112" ry="13" fill="#d8e2c9"/><path d="M145 171V88" stroke="#69835a" stroke-width="4"/><path d="M145 128C99 123 99 91 107 91C133 91 146 105 145 128" fill="#8fa978"/><path d="M146 109C182 111 195 84 186 83C160 83 145 92 146 109" fill="#a6ba86"/><path d="M113 151H178L166 186H126Z" fill="#d6a98a"/><path d="M108 150h75v10h-75z" fill="#e4b99b"/><circle cx="145" cy="68" r="26" fill="#e9c276"/><circle cx="145" cy="69" r="10" fill="#ac8755"/><path d="M65 174v-42M65 149c-31-5-26-22-26-22 22-1 27 14 26 22M65 157c25-4 23-23 23-23-19 0-24 13-23 23" stroke="#819469" stroke-width="3" fill="#a8bb8b"/><path d="M204 174v-27" stroke="#809366" stroke-width="3"/><circle cx="204" cy="137" r="11" fill="#e3c8a3"/><path d="M36 72l4-8 4 8 8 3-8 3-4 8-4-8-8-3zM205 46l3-6 3 6 6 2-6 2-3 6-3-6-6-2z" fill="#a9b88f"/></svg>`}
function tasksHTML(){let ids=plan(),ds=durations();return ids.map((id,i)=>{let t=tasks[id];return `<article class="card task"><div class="task-icon">${t.icon}</div><div class="task-body"><h3>${t.title}</h3><p>${t.desc}</p><div class="chips"><span class="chip">${t.area}</span><span class="chip">◷ ${ds[i]} 分鐘</span><span class="chip">${{easy:'輕鬆起步',normal:'穩穩練習',challenge:'小小挑戰'}[data().level]}</span></div></div><div class="task-actions">${completed(id)?'<span class="done">✓ 已打卡</span>':`<button class="secondary" data-start="${id}">開始 →</button>`}</div></article>`}).join('')}
function recommendation(){return {unknown:'先選擇今天的狀態，再依狀況調整練習。',ready:'精神不錯，從一個小步驟開始，照自己的節奏完成。',distracted:'先做紅綠燈活動，再把任務縮成一小步；提醒一次後，留時間回應。',angry:'先陪孩子平復情緒，再決定是否練習。情境演練留在平靜時進行。',tired:'今天先輕鬆動一動、觀察精神。持續想睡可休息，不必完成全部任務。'}[check()]}
function settings(){return `<div class="card"><div class="form-grid"><label>每日練習總長度<div class="range-line"><input id="minutes" type="range" min="5" max="15" value="${data().minutes}"><span id="minutesValue">${data().minutes} 分鐘</span></div></label><label>練習難度<select id="level"><option value="easy">輕鬆起步 · 一個步驟</option><option value="normal">穩穩練習 · 兩個步驟</option><option value="challenge">小小挑戰 · 自己安排</option></select></label></div><p class="subtext">時間是安排參考，可提早休息。難度只改變步驟與自主程度，不以速度評分。</p></div>`}
function home(){let p=profiles[child], ids=plan(),done=ids.filter(completed).length;return `<section class="hero"><span class="tag">SMALL STEPS, EVERY DAY</span><h1>${p.name}，今天也一起長大吧。</h1><p>每天 ${data().minutes} 分鐘，練習一點點專注，也多認識一點自己。<br>不用做到完美，願意開始就是很棒的一步。</p>${garden()}</section><div class="section-head"><h2>今天，感覺怎麼樣？ <small>先認識狀態，再開始練習</small></h2></div><div class="layout"><div><section class="card checkin"><h3>陪${p.name}選一個現在的感覺</h3><div class="mood-row">${[['ready','😊','精神不錯'],['distracted','🌀','有點分心'],['angry','🌧','心情不太好'],['tired','😴','有點想睡']].map(([v,e,t])=>`<button class="mood ${check()===v?'selected':''}" data-mood="${v}" aria-pressed="${check()===v}"><span>${e}</span>${t}</button>`).join('')}</div><div class="check-bottom"><span>狀態沒有對錯，每天都可以不一樣。</span><span>選擇即儲存 ✓</span></div></section><div class="section-head"><h2>今天的小任務 <small>依當下狀態安排</small></h2><a href="#tasks" class="text-link">調整練習 ↗</a></div>${tasksHTML()}</div><div><div class="card progress-card"><h3>今天的小小累積 <span style="float:right">🌱</span></h3><div class="big">${done} <small>/ ${ids.length} 個任務</small></div><div class="progress-track"><div style="width:${done/ids.length*100}%"></div></div><p>${done?'謝謝你願意練習，每一步都留下了足跡。':'花園準備好了，從一個小任務開始吧。'}</p>${weekChart()}</div><div class="card tip"><h3>✧ 給陪伴的你</h3><p>${recommendation()}</p><blockquote>${tasks[nextTask()||ids[0]].prompt}</blockquote>${nextTask()?`<button class="secondary full" data-start="${nextTask()}">下一個練習：${tasks[nextTask()].title} →</button>`:'<p>今天的任務都完成了，休息一下吧。</p>'}</div></div></div><p class="notice">✳ 這是日常陪伴與觀察工具，不提供診斷。資料僅儲存在此瀏覽器；換裝置前請於家長檢視匯出備份。</p>`}
function taskPage(){return `<h1 class="page-title">今天，練習一小步。</h1><p class="subtext">為${profiles[child].name}選一個舒服的節奏。${recommendation()}</p>${settings()}<div class="section-head"><h2>今日練習清單</h2><small>約 ${data().minutes} 分鐘</small></div><div class="layout"><div>${tasksHTML()}<div class="section-head"><h2>也可以選擇其他練習</h2></div>${Object.entries(tasks).filter(([id])=>!plan().includes(id)).map(([id,t])=>`<article class="card task"><div class="task-icon">${t.icon}</div><div class="task-body"><h3>${t.title}</h3><p>${t.desc}</p></div><button class="secondary" data-start="${id}">試試看</button></article>`).join('')}</div><div class="card tip" style="align-self:start;margin:0"><h3>家長陪伴小提醒</h3><p>一次給一個具體指令，留一點時間等待回應。<br>指出孩子做到的動作，避免用「你總是」評價。<br>情緒升高或想睡時，可以暫停。</p><blockquote>「你剛才分心後又回來了，我有看到你的努力。」</blockquote></div></div>`}
function recordPage(){return `<h1 class="page-title">把今天，輕輕記下來。</h1><p class="subtext">${profiles[child].name}的日常觀察。未知可以留白，不需要補猜數字。</p><div class="layout"><form id="logForm" class="card"><div class="form-grid"><label>紀錄日期<input name="date" type="date" value="${today()}" max="${today()}" required></label><label>觀察情境<select name="context"><option value="">尚未填寫</option><option>寫作業</option><option>閱讀</option><option>學校回饋</option><option>家庭活動</option><option>練習活動</option></select></label><label>情緒<select name="mood"><option value="">尚未觀察</option><option>平穩</option><option>開心</option><option>煩躁</option><option>生氣</option><option>難過</option></select></label><label>精神狀態<select name="energy"><option value="">尚未觀察</option><option>精神不錯</option><option>有點累</option><option>很想睡</option></select></label><label>分心次數<input name="distractions" type="number" min="0" max="999" placeholder="未知請留白"></label><label>家長提醒次數<input name="reminders" type="number" min="0" max="999" placeholder="未知請留白"></label><label>作業投入時間（分鐘）<input name="homework" type="number" min="0" max="600" placeholder="未知請留白"></label><label>恢復平靜時間（分鐘）<input name="calmMinutes" type="number" min="0" max="600" placeholder="未知請留白"></label><label class="wide">發生了什麼？什麼方式有幫助？<textarea name="note" maxlength="2000" placeholder="例如：第二題卡住後生氣；先休息，再提示第一步。"></textarea></label></div><details ${child==='girl'?'open':''}><summary style="margin:20px 0;color:#66755f">☾ 睡眠與白天精神觀察</summary><div class="form-grid"><label>昨晚上床時間<input type="time" name="bed"></label><label>昨晚估計入睡時間<input type="time" name="asleep"></label><label>今天起床時間<input type="time" name="wake"></label><label>估計睡眠時數<input name="sleepHours" type="number" min="0" max="24" step="0.1" placeholder="不清楚可留白"></label><label>打呼／鼻塞<select name="snore"><option value="">未知／未觀察</option><option>無觀察到</option><option>打呼</option><option>鼻塞</option><option>打呼與鼻塞</option></select></label><label>白天想睡的情境<select name="sleepy"><option value="">未知／未觀察</option><option>沒有觀察到</option><option>坐著看書</option><option>上課或考試</option><option>其他活動</option></select></label></div></details><button class="primary full">儲存今天的觀察</button></form><div><div class="card tip" style="margin:0"><h3>記錄事實，保留空白</h3><p>記下看見的行為、時間與協助方式。分心次數會隨活動長度不同而改變，不用拿兩個孩子互相比較。</p><p>睡眠與精神欄位用來整理觀察，不會推斷疾病或給予醫療評分。</p></div></div></div><div class="section-head"><h2>最近的日常紀錄</h2></div><div class="card">${logsHTML()}</div>`}
function logsHTML(){let list=[...data().logs].sort((a,b)=>b.date.localeCompare(a.date)||b.created-a.created);return list.length?list.map(l=>`<article class="record"><b>${esc(l.date)} · ${esc(l.context||'未填情境')}</b><p>${[l.mood,l.energy,l.distractions!==''?'分心 '+l.distractions+' 次':'',l.reminders!==''?'提醒 '+l.reminders+' 次':'',l.homework!==''?'作業 '+l.homework+' 分鐘':'',l.calmMinutes!==''?'平復 '+l.calmMinutes+' 分鐘':''].filter(Boolean).map(esc).join(' ／ ')||'尚未填寫狀態'}</p>${(l.bed||l.asleep||l.wake||l.sleepHours||l.snore||l.sleepy)?`<p>睡眠觀察：${esc([l.bed?'上床 '+l.bed:'',l.asleep?'入睡 '+l.asleep:'',l.wake?'起床 '+l.wake:'',l.sleepHours?'睡眠 '+l.sleepHours+' 小時':'',l.snore,l.sleepy].filter(Boolean).join(' ／ '))}</p>`:''}<p style="white-space:pre-wrap">${esc(l.note)}</p></article>`).join(''):'<div class="empty">這裡還沒有紀錄。<br>從今天的一個小觀察開始，不必填滿每一格。</div>'}
function average(logs,k){let values=logs.filter(l=>l[k]!==''&&l[k]!=null).map(l=>Number(l[k]));return values.length?{v:values.reduce((a,b)=>a+b,0)/values.length,n:values.length}:null}
function trend(k,label){let a=average(data().logs.filter(l=>week().includes(l.date)),k),b=average(data().logs.filter(l=>week(-1).includes(l.date)),k);return `<p>${label}：${a?`本週平均 ${a.v.toFixed(1)}（${a.n} 筆）`:'本週尚無資料'}${b?`；上週平均 ${b.v.toFixed(1)}（${b.n} 筆）`:'；上週尚無資料'}。${a&&b?'變化 '+(a.v-b.v>=0?'+':'')+(a.v-b.v).toFixed(1)+'；活動情境與時間可能不同，僅供觀察。':''}</p>`}
function parentPage(){let p=profiles[child],ss=sessionsIn(week()),days=new Set(ss.map(s=>s.date)).size,logs=data().logs.filter(l=>week().includes(l.date));return `<h1 class="page-title">陪伴的足跡。</h1><p class="subtext">${p.full}的個別檔案與每週觀察 · ${week()[0]} — ${week()[6]}</p><div class="stats"><div class="card stat"><span>本週練習日</span><strong>${days}<small style="font-size:13px"> / 7 天</small></strong><span>有打卡的不同日期</span></div><div class="card stat"><span>本週完成練習</span><strong>${ss.length}<small style="font-size:13px"> 次</small></strong><span>包含自主選擇的練習</span></div><div class="card stat"><span>本週日常觀察</span><strong>${logs.length}<small style="font-size:13px"> 筆</small></strong><span>保留每次真實觀察</span></div></div><div class="layout"><div><div class="card"><h3 style="margin-top:0">這週的小步趨勢</h3>${weekChart()}<div class="subtext">${trend('distractions','分心次數')}${trend('reminders','提醒次數')}${trend('sleepHours','估計睡眠時數')}<p>情緒紀錄：${['平穩','開心','煩躁','生氣','難過'].map(m=>`${m} ${logs.filter(l=>l.mood===m).length} 筆`).join(' · ')}。未填情緒 ${logs.filter(l=>!l.mood).length} 筆。</p><p>下一個練習建議：${recommendation()} ${nextTask()?'建議下一個練習：「'+tasks[nextTask()].title+'」。':'今日任務已完成，可以休息。'}</p></div></div><div class="section-head"><h2>孩子的個別檔案</h2></div><form class="card" id="profileForm"><b>${p.full} · ${p.age} · ${p.grade}</b><p class="subtext">生日 ${p.birth} · 年齡與年級以 2026/11 家長資訊為基準</p><ul class="profile-points">${p.traits.map(t=>`<li>${t}</li>`).join('')}</ul><p class="subtext">${p.unknown}</p><label>補充或更新觀察<textarea id="extra" maxlength="4000" placeholder="可填寫未知項目，或說明上述特徵的最新變化。">${esc(data().extra)}</textarea></label><button class="secondary full">儲存補充內容</button></form></div><div><div class="card tip" style="margin:0"><h3>資料與備份</h3><p>資料只存在目前瀏覽器，不會跨裝置同步。清除瀏覽器資料可能使紀錄消失；定期匯出，換裝置後再匯入。</p><button id="export" class="secondary full">↓ 匯出兩位孩子的紀錄</button><label class="secondary full" style="display:block;text-align:center;cursor:pointer">↑ 匯入備份<input id="import" type="file" accept="application/json,.json" style="display:none"></label><p>匯入會合併紀錄並略過重複項目；原有資料會保留。檔案包含家庭觀察資訊，請妥善保存。</p></div><div class="card tip"><h3>陪伴，不是評分</h3><p>本工具不診斷 ADHD 或其他疾病，也不以紀錄推論疾病。練習以日常習慣與親子陪伴為目的。</p><p>兩個孩子各自累積，不做排名。沒有資料的日期保留空白，不算失敗。</p></div></div></div><div class="section-head"><h2>練習打卡紀錄</h2></div><div class="card">${data().sessions.length?[...data().sessions].sort((a,b)=>b.created-a.created).slice(0,30).map(s=>`<div class="record"><b>${esc(s.date)} · ${esc(tasks[s.task]?.title||s.task)}</b><p>${esc(s.level)} · 安排 ${s.planned} 分鐘 · 實際計時 ${Math.floor(s.elapsed/60)} 分 ${s.elapsed%60} 秒 · 分心 ${s.distractions} 次${s.elapsed<s.planned*60?' · 提早結束':''}</p></div>`).join(''):'<div class="empty">完成一個練習後，足跡就會出現在這裡。</div>'}</div>`}
function render(){page=location.hash.slice(1)||'home';if(!['home','tasks','records','parent'].includes(page))page='home';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));document.querySelectorAll('[data-child]').forEach(b=>b.classList.toggle('selected',b.dataset.child===child));$('#app').innerHTML=({home, tasks:taskPage,records:recordPage,parent:parentPage}[page])();if($('#level')){$('#level').value=data().level;$('#level').onchange=e=>{data().level=e.target.value;save();render()};$('#minutes').oninput=e=>$('#minutesValue').textContent=e.target.value+' 分鐘';$('#minutes').onchange=e=>{data().minutes=Number(e.target.value);save();render()}}
 document.querySelectorAll('[data-mood]').forEach(b=>b.onclick=()=>{data().checks[today()]=b.dataset.mood;save();render()});document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));
 if($('#logForm'))$('#logForm').onsubmit=e=>{e.preventDefault();let l=Object.fromEntries(new FormData(e.target));l.id=crypto.randomUUID();l.created=Date.now();data().logs.push(l);save();render();toast('今天的觀察已儲存。')};if($('#profileForm'))$('#profileForm').onsubmit=e=>{e.preventDefault();data().extra=$('#extra').value;save();toast('補充內容已儲存。')};if($('#export')){$('#export').onclick=exportData;$('#import').onchange=importData}}
function start(id){clearInterval(interval);interval=null;currentTask={id,child,level:data().level,planned:durations()[plan().indexOf(id)]||Math.max(2,Math.round(data().minutes/3)),date:today()};total=currentTask.planned*60;remaining=total;$('#exerciseTitle').textContent=tasks[id].title;$('#exerciseInstructions').textContent=tasks[id].steps[currentTask.level];$('#exercisePrompt').textContent='家長提示語｜'+tasks[id].prompt;$('#sessionDistraction').value=0;$('#toggleTimer').textContent='開始計時';updateClock();$('#exercise').showModal()}
function updateClock(){$('#clock').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');$('#timer').style.setProperty('--progress',(total-remaining)/total*100+'%')}
function tick(){remaining=Math.max(0,Math.ceil((endTime-Date.now())/1000));updateClock();if(remaining===0){clearInterval(interval);interval=null;$('#toggleTimer').textContent='計時完成';toast('時間到了，可以休息，再決定是否打卡。')}}
$('#toggleTimer').onclick=()=>{if(!remaining)return;if(interval){tick();clearInterval(interval);interval=null;$('#toggleTimer').textContent='繼續計時'}else{endTime=Date.now()+remaining*1000;interval=setInterval(tick,250);$('#toggleTimer').textContent='暫停'}};$('#resetTimer').onclick=()=>{clearInterval(interval);interval=null;remaining=total;updateClock();$('#toggleTimer').textContent='開始計時'};
$('#finishTask').onclick=()=>{let n=Number($('#sessionDistraction').value);if(!Number.isInteger(n)||n<0||n>999){toast('請輸入 0–999 的分心次數。');return}if(interval)tick();clearInterval(interval);interval=null;let d=db.children[currentTask.child];d.sessions.push({id:crypto.randomUUID(),date:currentTask.date,task:currentTask.id,planned:currentTask.planned,elapsed:total-remaining,level:{easy:'輕鬆起步',normal:'穩穩練習',challenge:'小小挑戰'}[currentTask.level],distractions:n,created:Date.now()});save();$('#exercise').close();render();toast('打卡完成！每一小步，都算數。')};$('#exercise').addEventListener('close',()=>{clearInterval(interval);interval=null});
function exportData(){let url=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='小步日常_家庭紀錄_'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已匯出兩位孩子的備份。')}
async function importData(e){let f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error();let incoming=JSON.parse(await f.text());if(incoming.version!==1||!incoming.children)throw Error();for(let c of ['girl','boy']){let d=incoming.children[c];if(!d||!Array.isArray(d.logs)||!Array.isArray(d.sessions)||typeof d.checks!=='object'||d.checks===null)throw Error();if(d.logs.some(l=>typeof l.id!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(l.date)||typeof l.created!=='number')||d.sessions.some(s=>typeof s.id!=='string'||!tasks[s.task]||!/^\d{4}-\d{2}-\d{2}$/.test(s.date)||!Number.isFinite(s.planned)||!Number.isFinite(s.elapsed)||!Number.isFinite(s.distractions)||typeof s.created!=='number'))throw Error()}
 let merged=structuredClone(db);for(let c of ['girl','boy']){let from=incoming.children[c],to=merged.children[c];for(let k of ['logs','sessions']){let ids=new Set(to[k].map(x=>x.id));to[k].push(...from[k].filter(x=>!ids.has(x.id)))}for(let [date,state] of Object.entries(from.checks)){if(/^\d{4}-\d{2}-\d{2}$/.test(date)&&['ready','distracted','angry','tired'].includes(state)&&!to.checks[date])to.checks[date]=state}if(!to.extra&&typeof from.extra==='string')to.extra=from.extra}db=merged;save();render();toast('備份已合併，原有紀錄已保留。')}catch{toast('無法匯入，請選擇由本工具匯出的有效 JSON 備份。')}}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});document.querySelectorAll('[data-child]').forEach(b=>b.onclick=()=>{child=b.dataset.child;render()});$('#date').textContent=new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(new Date());render();
